\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 1269 (NT-062). CC BY 4.0. \url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Michel Waldschmidt, \emph{Open Diophantine Problems}, arXiv:math/0312440 (version dated January 24, 2004), Section 2.2, pp.\ 16--17, discussion of Waring\textquotesingle s problem. \url{https://arxiv.org/pdf/math/0312440}.
\item[S3] J\"org Br\"udern and Trevor D. Wooley, \emph{On Waring\textquotesingle s problem for larger powers}, arXiv:2211.10380v1 (2022), Section 1, p.\ 1. \url{https://arxiv.org/pdf/2211.10380v1}.
\end{description}
